import{_ as e,c as r,a5 as a,o}from"./chunks/framework.mFcBg5UA.js";const l="/my-blog/img/electron_summer/image1.png",i="/my-blog/img/electron_summer/image2.png",n="/my-blog/img/electron_summer/image3.png",d="/my-blog/img/electron_summer/image4.png",s="/my-blog/img/electron_summer/image5.png",c="/my-blog/img/electron_summer/image6.png",h="/my-blog/img/electron_summer/image7.jpg",f=JSON.parse('{"title":"十年跨平台开发，Electron 凭什么占据一席之地？","titleTemplate":"Electron实战","description":"","frontmatter":{"outline":"deep","title":"十年跨平台开发，Electron 凭什么占据一席之地？","titleTemplate":"Electron实战","head":[["link",{"rel":"canonical","href":"https://luffy-d-lufei.github.io/my-blog/summary/electron/electron_summer.html"}]]},"headers":[],"relativePath":"summary/electron/electron_summer.md","filePath":"summary/electron/electron_summer.md","lastUpdated":1727279249000}'),p={name:"summary/electron/electron_summer.md"};function m(u,t,g,b,k,E){return o(),r("div",null,t[0]||(t[0]=[a('<h1 id="十年跨平台开发-electron-凭什么占据一席之地" tabindex="-1">十年跨平台开发，Electron 凭什么占据一席之地？ <a class="header-anchor" href="#十年跨平台开发-electron-凭什么占据一席之地" aria-label="Permalink to &quot;十年跨平台开发，Electron 凭什么占据一席之地？&quot;">​</a></h1><p><img src="'+l+'" alt="image.png"></p><p>大家好，我是徐徐。今天我们来认识认识 Electron。</p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>其实一直想系统的写一写 Electron 相关的文章，之前在掘金上写过，但是现在来看那些文章都写得挺粗糙的，所以现在我决定系统整理相关的知识，输出自己更多 Electron 开发相关的经验。这一节我们主要是来认识一下 Electron，这个已经有 10 年历史的跨端开发框架。我将从诞生背景，优劣势，生态，案例以及和其他框架的对比这几个方面带大家来认识 Electron。</p><h2 id="electron-诞生背景" tabindex="-1">Electron 诞生背景 <a class="header-anchor" href="#electron-诞生背景" aria-label="Permalink to &quot;Electron 诞生背景&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>Electron 的背景还是很强劲的，下面我们就来看看它是如何诞生的。</p><h3 id="起源" tabindex="-1">起源 <a class="header-anchor" href="#起源" aria-label="Permalink to &quot;起源&quot;">​</a></h3><p>Electron 的前身 Atom Shell，由 GitHub 的开发者在 2013 年创建的，当时 Atom 需要一个能够在桌面环境中运行的跨平台框架，同时能够利用 web 技术构建现代化的用户界面，于是就有了 Electron 的雏形。</p><h3 id="需求-web-技术的发展" tabindex="-1">需求 &amp; Web 技术的发展 <a class="header-anchor" href="#需求-web-技术的发展" aria-label="Permalink to &quot;需求 &amp; Web 技术的发展&quot;">​</a></h3><p>互联网的兴起使得桌面端的需求日益增长，传统的桌面应用开发需要针对每个操作系统（Windows、macOS、Linux）分别编写代码，这增加了开发和维护成本，所以非常需要可以通过一次开发实现多平台支持的框架。</p><p>随着 HTML5、CSS3 和 JavaScript 的快速发展，web 技术变得越来越强大和灵活。开发者希望能够利用这些技术构建现代化的用户界面，并且享受 web 开发工具和框架带来的便利。这使得更加需要一款跨端大杀器架来支持开发者，Electron 应运而生。</p><h3 id="发展历程" tabindex="-1">发展历程 <a class="header-anchor" href="#发展历程" aria-label="Permalink to &quot;发展历程&quot;">​</a></h3><p><img src="'+n+'" alt=""></p><ul><li><strong>2013 年</strong>：Atom Shell 诞生，最初用于 GitHub 的 Atom 编辑器。</li><li><strong>2014 年 2 月</strong>：Atom 编辑器对外发布，Atom Shell 作为其核心技术。</li><li><strong>2015 年 4 月</strong>：Atom Shell 更名为 Electron，并作为一个独立项目发布。随着时间的推移，Electron 的功能和社区支持不断增强。</li><li><strong>2016 年</strong>：Electron 的应用开始广泛传播，许多公司和开发者开始使用 Electron 构建跨平台桌面应用。</li><li><strong>2020 年</strong>：Electron 发布 10.0 版本，进一步增强了稳定性和性能。</li><li><strong>2023 年</strong>：Electron 10 周年</li></ul><p>更多可以参考：</p><p><a href="https://www.electronjs.org/blog/electron" target="_blank" rel="noreferrer">https://www.electronjs.org/blog/electron</a></p><h2 id="electron-优势" tabindex="-1">Electron 优势 <a class="header-anchor" href="#electron-优势" aria-label="Permalink to &quot;Electron 优势&quot;">​</a></h2><p>Electron 的优势非常的明显，大概总结为下面四个方面。</p><h3 id="跨平台支持" tabindex="-1">跨平台支持 <a class="header-anchor" href="#跨平台支持" aria-label="Permalink to &quot;跨平台支持&quot;">​</a></h3><p>Electron 的最大优势在于其跨平台特性。开发者可以编写一次代码，Electron 会处理不同操作系统之间的差异，使应用能够在 Windows、macOS 和 Linux 上无缝运行。</p><h3 id="前端技术栈" tabindex="-1">前端技术栈 <a class="header-anchor" href="#前端技术栈" aria-label="Permalink to &quot;前端技术栈&quot;">​</a></h3><p>Electron 应用使用 HTML、CSS 和 JavaScript 构建界面。开发者可以使用流行的前端框架和工具（如 React、Vue.js、Angular）来开发应用，提高开发效率和代码质量。</p><h3 id="node-js-集成" tabindex="-1">Node.js 集成 <a class="header-anchor" href="#node-js-集成" aria-label="Permalink to &quot;Node.js 集成&quot;">​</a></h3><p>Electron 将 Chromium 和 Node.js 集成在一起，这使得应用不仅可以使用 web 技术构建界面，还可以使用 Node.js 访问底层系统资源，如文件系统、网络、进程等。</p><h3 id="强大社区" tabindex="-1">强大社区 <a class="header-anchor" href="#强大社区" aria-label="Permalink to &quot;强大社区&quot;">​</a></h3><p>Electron 拥有丰富的文档、教程、示例和强大的社区支持。开发者可以很容易地找到解决问题的方法和最佳实践，从而加快开发速度。</p><h2 id="electron-劣势" tabindex="-1">Electron 劣势 <a class="header-anchor" href="#electron-劣势" aria-label="Permalink to &quot;Electron 劣势&quot;">​</a></h2><p>当然，一个东西都有两面性，有优势肯定也有劣势，劣势大概总结为以下几个方面。</p><h3 id="性能问题" tabindex="-1">性能问题 <a class="header-anchor" href="#性能问题" aria-label="Permalink to &quot;性能问题&quot;">​</a></h3><p>Electron 应用由于需要运行一个完整的 Chromium 实例，通常会占用较高的内存和 CPU 资源，性能相对较差。这在资源有限的设备上（如老旧计算机）尤为明显。</p><h3 id="打包体积大" tabindex="-1">打包体积大 <a class="header-anchor" href="#打包体积大" aria-label="Permalink to &quot;打包体积大&quot;">​</a></h3><p>由于需要包含 Chromium 和 Node.js 运行时，Electron 应用的打包体积较大。一个简单的 Electron 应用的打包体积可能达到几十到上百 MB，这对于一些应用场景来说是不小的负担。</p><h3 id="安全性" tabindex="-1">安全性 <a class="header-anchor" href="#安全性" aria-label="Permalink to &quot;安全性&quot;">​</a></h3><p>Electron 应用需要处理 web 技术带来的安全问题，如跨站脚本（XSS）攻击和远程代码执行（RCE）漏洞。开发者需要特别注意安全性，采取适当的防护措施（如使用 <code>contextIsolation</code>、<code>sandbox</code>、<code>Content Security Policy</code> 等）。</p><h2 id="生态" tabindex="-1">生态 <a class="header-anchor" href="#生态" aria-label="Permalink to &quot;生态&quot;">​</a></h2><p>上面谈到了 Electron 的优势和劣势，下面我们来看看 Electron 的生态。对于一款开源框架，生态是非常关键的，社区活跃度以及相应的配套工具非常影响框架的生态，如果有众多的开发者支持和维护这个框架，那么它的生态才会越来越好。Electron 的生态依托于 Node.js 发展出了很多很多开源工具，其生态是相当的繁荣。下面可以看看两张图就知道其生态的繁荣之处。</p><ul><li><strong>GitHub 情况</strong></li></ul><p><img src="'+d+'" alt=""></p><ul><li><strong>NPM 情况</strong></li></ul><p><img src="'+s+'" alt=""></p><p>下面是一些常见的相关生态工具。</p><h3 id="打包和分发工具" tabindex="-1">打包和分发工具 <a class="header-anchor" href="#打包和分发工具" aria-label="Permalink to &quot;打包和分发工具&quot;">​</a></h3><ul><li><strong>electron-packager</strong>：用于将 Electron 应用打包成可执行文件。支持多平台打包，简单易用。</li><li><strong>electron-builder</strong>：一个功能强大的打包工具，支持自动更新、多平台打包和安装程序制作。</li></ul><h3 id="测试工具" tabindex="-1">测试工具 <a class="header-anchor" href="#测试工具" aria-label="Permalink to &quot;测试工具&quot;">​</a></h3><ul><li><strong>Spectron</strong>：基于 WebDriver，用于 Electron 应用的端到端测试。支持模拟用户操作和验证应用行为。</li><li><strong>electron-mocha</strong>：用于在 Electron 环境中运行 Mocha 测试，适合进行单元测试和集成测试。</li></ul><h3 id="开发工具" tabindex="-1">开发工具 <a class="header-anchor" href="#开发工具" aria-label="Permalink to &quot;开发工具&quot;">​</a></h3><ul><li><strong>Electron Forge</strong>：一个集成开发工具，简化了 Electron 应用的开发、打包和分发流程。支持脚手架、插件系统和自动更新。</li><li><strong>Electron DevTools</strong>：调试和分析 Electron 应用性能的工具，帮助开发者优化应用性能。</li></ul><h2 id="案例" tabindex="-1">案例 <a class="header-anchor" href="#案例" aria-label="Permalink to &quot;案例&quot;">​</a></h2><p><img src="'+c+'" alt=""></p><p>用 Electron开发的软件非常多，国内外都有很多知名的软件，有了成功的案例才会吸引更多的开发者使用它，下面是一些举例。</p><h3 id="国内" tabindex="-1">国内 <a class="header-anchor" href="#国内" aria-label="Permalink to &quot;国内&quot;">​</a></h3><ul><li>QQ</li><li>微信开发者工具</li><li>百度网盘</li><li>语雀</li><li>网易灵犀办公</li><li>网易云音乐</li></ul><h3 id="国外" tabindex="-1">国外 <a class="header-anchor" href="#国外" aria-label="Permalink to &quot;国外&quot;">​</a></h3><ul><li>Visual Studio Code</li><li>Slack</li><li>Discord</li><li>GitHub Desktop</li><li>Postman</li><li>WhatsApp</li></ul><p>其他更多可参考：<a href="https://www.electronjs.org/apps" target="_blank" rel="noreferrer">https://www.electronjs.org/apps</a></p><p>一个小技巧，Mac 电脑检测应用是否是 Electron 框架，在命令行运行如下代码：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;[ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  $app/Contents/Frameworks/Electron</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Framework.framework ] &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $app; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span></code></pre></div><h2 id="和其他跨端框架的对比" tabindex="-1">和其他跨端框架的对比 <a class="header-anchor" href="#和其他跨端框架的对比" aria-label="Permalink to &quot;和其他跨端框架的对比&quot;">​</a></h2><p><img src="'+h+'" alt=""></p><p>一个框架的诞生避免不了与同类型的框架对比，下面是一个对比表格，展示了 Electron 与其他流行的跨端桌面应用开发框架（如 NW.js、Proton Native、Tauri 和 Flutter Desktop）的优缺点和特性：</p><table tabindex="0"><thead><tr><th>特性</th><th>Electron</th><th>NW.js</th><th>Proton Native</th><th>Tauri</th><th>Flutter Desktop</th></tr></thead><tbody><tr><td><strong>开发语言</strong></td><td>JavaScript, HTML, CSS</td><td>JavaScript, HTML, CSS</td><td>JavaScript, React</td><td>Rust, JavaScript, HTML, CSS</td><td>Dart</td></tr><tr><td><strong>框架大小</strong></td><td>大（几十到几百 MB）</td><td>中等（几十 MB）</td><td>中等（几十 MB）</td><td>小（几 MB）</td><td>大（几十到几百 MB）</td></tr><tr><td><strong>性能</strong></td><td>中等</td><td>中等</td><td>中等</td><td>高</td><td>高</td></tr><tr><td><strong>跨平台支持</strong></td><td>Windows, macOS, Linux</td><td>Windows, macOS, Linux</td><td>Windows, macOS, Linux</td><td>Windows, macOS, Linux</td><td>Windows, macOS, Linux</td></tr><tr><td><strong>使用的技术栈</strong></td><td>Chromium, Node.js</td><td>Chromium, Node.js</td><td>React, Node.js</td><td>Rust, WebView</td><td>Flutter Engine</td></tr><tr><td><strong>生态系统和社区</strong></td><td>非常活跃，生态丰富</td><td>活跃</td><td>停滞了</td><td>新兴，快速增长</td><td>活跃，现阶段更新不频繁</td></tr><tr><td><strong>开发难度</strong></td><td>易于上手</td><td>易于上手</td><td>需要 React 知识</td><td>需要 Rust 和前端知识</td><td>需要 Dart 知识</td></tr><tr><td><strong>自动更新支持</strong></td><td>内置支持</td><td>需要手动实现</td><td>需要手动实现</td><td>需要手动实现</td><td>需要手动实现</td></tr><tr><td><strong>原生功能访问</strong></td><td>通过 Node.js 模块访问</td><td>通过 Node.js 模块访问</td><td>通过 Node.js 和原生模块访问</td><td>通过 Rust 原生模块访问</td><td>通过插件和原生模块访问</td></tr><tr><td><strong>热重载和开发体验</strong></td><td>支持（需要配置）</td><td>支持（需要配置）</td><td>支持（需要配置）</td><td>支持（需要配置）</td><td>支持（内置支持）</td></tr><tr><td><strong>打包和发布</strong></td><td>Electron Builder, Forge</td><td>nw-builder</td><td>需要手动配置打包工具</td><td>Tauri 打包工具</td><td>Flutter build tools</td></tr><tr><td><strong>常见应用场景</strong></td><td>聊天应用、生产力工具、IDE</td><td>聊天应用、生产力工具</td><td>小型工具和实用程序</td><td>轻量级、性能要求高的应用</td><td>跨平台移动和桌面应用</td></tr><tr><td><strong>知名应用</strong></td><td>VS Code, Slack, Discord, 知名应用</td><td>WebTorrent, 其他工具</td><td>小型 React 工具和应用</td><td>新兴应用和工具</td><td>仅少数桌面应用，Flutter主打移动应用</td></tr></tbody></table><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>Electron 是一个强大的跨平台开发框架，其诞生对前端开发者的意义非常大，让很多从事前端的开发者也有机会开发桌面客户端，扩大了前端开发工程师的岗位需求。当然，它不一定是最好的框架，因为适合自己的才是最好的，主要还是看自己的业务场景和技术需要，优势和劣势都是需要考虑的，仁者见仁，智者见智。</p>',65)]))}const x=e(p,[["render",m]]);export{f as __pageData,x as default};
